import { FormEvent, useMemo, useState } from 'react'

type TodoItem = {
  id: string
  title: string
  completed: boolean
}

type TodoList = {
  id: string
  title: string
  description: string
  items: TodoItem[]
}

const initialLists: TodoList[] = [
  {
    id: 'product',
    title: 'Producto',
    description: 'Tareas para ajustar la experiencia inicial.',
    items: [
      { id: 'product-1', title: 'Definir contratos REST', completed: false },
      { id: 'product-2', title: 'Validar estados vacios', completed: true },
      { id: 'product-3', title: 'Revisar copy de acciones', completed: false },
    ],
  },
  {
    id: 'delivery',
    title: 'Delivery',
    description: 'Seguimiento operativo del sprint actual.',
    items: [
      { id: 'delivery-1', title: 'Preparar demo navegable', completed: true },
      { id: 'delivery-2', title: 'Documentar endpoints necesarios', completed: false },
    ],
  },
]

function createId(prefix: string) {
  return `${prefix}-${Date.now().toString(36)}`
}

function App() {
  const [lists, setLists] = useState<TodoList[]>(initialLists)
  const [selectedListId, setSelectedListId] = useState(initialLists[0].id)
  const [newListTitle, setNewListTitle] = useState('')
  const [newItemTitle, setNewItemTitle] = useState('')
  const [editingListId, setEditingListId] = useState<string | null>(null)
  const [editingItemId, setEditingItemId] = useState<string | null>(null)
  const [draftTitle, setDraftTitle] = useState('')

  const selectedList = lists.find((list) => list.id === selectedListId) ?? lists[0]

  const totals = useMemo(() => {
    const itemCount = lists.reduce((count, list) => count + list.items.length, 0)
    const completedCount = lists.reduce(
      (count, list) => count + list.items.filter((item) => item.completed).length,
      0,
    )

    return { itemCount, completedCount, pendingCount: itemCount - completedCount }
  }, [lists])

  function addList(event: FormEvent<HTMLFormElement>) {
    event.preventDefault()

    const title = newListTitle.trim()
    if (!title) {
      return
    }

    const list: TodoList = {
      id: createId('list'),
      title,
      description: 'Nueva lista de trabajo.',
      items: [],
    }

    setLists((currentLists) => [...currentLists, list])
    setSelectedListId(list.id)
    setNewListTitle('')
  }

  function deleteList(listId: string) {
    setLists((currentLists) => {
      const nextLists = currentLists.filter((list) => list.id !== listId)
      if (selectedListId === listId) {
        setSelectedListId(nextLists[0]?.id ?? '')
      }

      return nextLists
    })
  }

  function startListEdit(list: TodoList) {
    setEditingItemId(null)
    setEditingListId(list.id)
    setDraftTitle(list.title)
  }

  function saveListTitle(listId: string) {
    const title = draftTitle.trim()
    if (!title) {
      return
    }

    setLists((currentLists) =>
      currentLists.map((list) => (list.id === listId ? { ...list, title } : list)),
    )
    setEditingListId(null)
    setDraftTitle('')
  }

  function addItem(event: FormEvent<HTMLFormElement>) {
    event.preventDefault()

    const title = newItemTitle.trim()
    if (!title || !selectedList) {
      return
    }

    const item: TodoItem = {
      id: createId('item'),
      title,
      completed: false,
    }

    setLists((currentLists) =>
      currentLists.map((list) =>
        list.id === selectedList.id ? { ...list, items: [...list.items, item] } : list,
      ),
    )
    setNewItemTitle('')
  }

  function toggleItem(itemId: string) {
    setLists((currentLists) =>
      currentLists.map((list) =>
        list.id === selectedList.id
          ? {
              ...list,
              items: list.items.map((item) =>
                item.id === itemId ? { ...item, completed: !item.completed } : item,
              ),
            }
          : list,
      ),
    )
  }

  function startItemEdit(item: TodoItem) {
    setEditingListId(null)
    setEditingItemId(item.id)
    setDraftTitle(item.title)
  }

  function saveItemTitle(itemId: string) {
    const title = draftTitle.trim()
    if (!title) {
      return
    }

    setLists((currentLists) =>
      currentLists.map((list) =>
        list.id === selectedList.id
          ? {
              ...list,
              items: list.items.map((item) => (item.id === itemId ? { ...item, title } : item)),
            }
          : list,
      ),
    )
    setEditingItemId(null)
    setDraftTitle('')
  }

  function deleteItem(itemId: string) {
    setLists((currentLists) =>
      currentLists.map((list) =>
        list.id === selectedList.id
          ? { ...list, items: list.items.filter((item) => item.id !== itemId) }
          : list,
      ),
    )
  }

  const selectedCompleted = selectedList.items.filter((item) => item.completed).length
  const selectedPending = selectedList.items.length - selectedCompleted

  return (
    <main className="app-shell">
      <aside className="sidebar" aria-label="Todo lists">
        <div className="brand">
          <span className="brand-mark" aria-hidden="true">
            TD
          </span>
          <div>
            <h1>TodoList</h1>
            <p>Gestion de listas e items</p>
          </div>
        </div>

        <form className="compact-form" onSubmit={addList}>
          <input
            aria-label="Nombre de nueva lista"
            onChange={(event) => setNewListTitle(event.target.value)}
            placeholder="Nueva lista"
            value={newListTitle}
          />
          <button type="submit">Add</button>
        </form>

        <nav className="list-nav">
          {lists.map((list) => (
            <button
              className={list.id === selectedList.id ? 'list-link active' : 'list-link'}
              key={list.id}
              onClick={() => setSelectedListId(list.id)}
              type="button"
            >
              <span>{list.title}</span>
              <small>{list.items.length}</small>
            </button>
          ))}
        </nav>
      </aside>

      <section className="workspace" aria-label="Selected todo list">
        <header className="workspace-header">
          <div>
            {editingListId === selectedList.id ? (
              <div className="edit-row">
                <input
                  aria-label="Editar nombre de lista"
                  autoFocus
                  onChange={(event) => setDraftTitle(event.target.value)}
                  value={draftTitle}
                />
                <button onClick={() => saveListTitle(selectedList.id)} type="button">
                  Save
                </button>
              </div>
            ) : (
              <h2>{selectedList.title}</h2>
            )}
            <p>{selectedList.description}</p>
          </div>

          <div className="header-actions">
            <button onClick={() => startListEdit(selectedList)} type="button">
              Edit
            </button>
            <button
              className="danger"
              disabled={lists.length === 1}
              onClick={() => deleteList(selectedList.id)}
              type="button"
            >
              Delete
            </button>
          </div>
        </header>

        <form className="item-form" onSubmit={addItem}>
          <input
            aria-label="Nuevo item"
            onChange={(event) => setNewItemTitle(event.target.value)}
            placeholder="Agregar item a esta lista"
            value={newItemTitle}
          />
          <button type="submit">Add item</button>
        </form>

        <div className="item-list">
          {selectedList.items.length === 0 ? (
            <div className="empty-state">
              <strong>No hay items</strong>
              <span>Agrega el primer item para empezar a trabajar esta lista.</span>
            </div>
          ) : (
            selectedList.items.map((item) => (
              <article className={item.completed ? 'todo-item completed' : 'todo-item'} key={item.id}>
                <label>
                  <input
                    checked={item.completed}
                    onChange={() => toggleItem(item.id)}
                    type="checkbox"
                  />
                  {editingItemId === item.id ? (
                    <input
                      aria-label="Editar item"
                      autoFocus
                      className="inline-input"
                      onChange={(event) => setDraftTitle(event.target.value)}
                      value={draftTitle}
                    />
                  ) : (
                    <span>{item.title}</span>
                  )}
                </label>

                <div className="row-actions">
                  {editingItemId === item.id ? (
                    <button onClick={() => saveItemTitle(item.id)} type="button">
                      Save
                    </button>
                  ) : (
                    <button onClick={() => startItemEdit(item)} type="button">
                      Edit
                    </button>
                  )}
                  <button className="danger" onClick={() => deleteItem(item.id)} type="button">
                    Delete
                  </button>
                </div>
              </article>
            ))
          )}
        </div>
      </section>

      <aside className="inspector" aria-label="Summary">
        <h2>Resumen</h2>
        <dl>
          <div>
            <dt>Listas</dt>
            <dd>{lists.length}</dd>
          </div>
          <div>
            <dt>Items</dt>
            <dd>{totals.itemCount}</dd>
          </div>
          <div>
            <dt>Pendientes</dt>
            <dd>{totals.pendingCount}</dd>
          </div>
          <div>
            <dt>Completados</dt>
            <dd>{totals.completedCount}</dd>
          </div>
        </dl>

        <div className="selected-summary">
          <span>Lista actual</span>
          <strong>{selectedList.title}</strong>
          <p>
            {selectedPending} pendientes, {selectedCompleted} completados.
          </p>
        </div>
      </aside>
    </main>
  )
}

export default App

