import type {
  ApiProblem,
  ApiTodoItem,
  ApiTodoList,
  ApiTodoListDetail,
  SaveTodoItemPayload,
  SaveTodoListPayload,
  TodoItem,
  TodoList,
} from './types'

const API_BASE_URL = import.meta.env.VITE_API_BASE_URL ?? '/api'

export class ApiError extends Error {
  status: number
  code?: string
  detail?: string

  constructor(status: number, problem?: ApiProblem) {
    super(problem?.detail ?? problem?.title ?? `Request failed with status ${status}`)
    this.name = 'ApiError'
    this.status = status
    this.code = problem?.code ?? problem?.errorCode
    this.detail = problem?.detail
  }
}

function buildUrl(path: string) {
  return `${API_BASE_URL.replace(/\/$/, '')}${path}`
}

async function parseProblem(response: Response) {
  try {
    return (await response.json()) as ApiProblem
  } catch {
    return undefined
  }
}

async function request<T>(path: string, init?: RequestInit): Promise<T> {
  const response = await fetch(buildUrl(path), {
    headers: {
      Accept: 'application/json',
      ...(init?.body ? { 'Content-Type': 'application/json' } : {}),
      ...init?.headers,
    },
    ...init,
  })

  if (!response.ok) {
    throw new ApiError(response.status, await parseProblem(response))
  }

  if (response.status === 204) {
    return undefined as T
  }

  return (await response.json()) as T
}

function mapItem(item: ApiTodoItem): TodoItem {
  return {
    id: item.id,
    title: item.name,
    completed: item.is_completed ?? item.isCompleted ?? false,
    todoListId: item.todo_list_id ?? item.todoListId ?? 0,
    externalId: item.external_id,
    updatedAt: item.updated_at,
  }
}

function mapList(list: ApiTodoListDetail): TodoList {
  return {
    id: list.id,
    title: list.name,
    description: list.external_id ? `External: ${list.external_id}` : 'Lista local',
    items: list.items.map(mapItem),
    externalId: list.external_id,
    updatedAt: list.updated_at,
  }
}

export async function getTodoLists() {
  const lists = await request<ApiTodoList[]>('/todolists')
  const details = await Promise.all(lists.map((list) => getTodoList(list.id)))

  return details
}

export async function getTodoList(id: number) {
  return mapList(await request<ApiTodoListDetail>(`/todolists/${id}`))
}

export async function createTodoList(payload: SaveTodoListPayload) {
  const list = await request<ApiTodoList>('/todolists', {
    method: 'POST',
    body: JSON.stringify(payload),
  })

  return getTodoList(list.id)
}

export async function updateTodoList(id: number, payload: SaveTodoListPayload) {
  const list = await request<ApiTodoList>(`/todolists/${id}`, {
    method: 'PUT',
    body: JSON.stringify(payload),
  })

  return getTodoList(list.id)
}

export async function deleteTodoList(id: number) {
  await request<void>(`/todolists/${id}`, { method: 'DELETE' })
}

export async function createTodoItem(todoListId: number, payload: SaveTodoItemPayload) {
  const item = await request<ApiTodoItem>(`/todolists/${todoListId}/items`, {
    method: 'POST',
    body: JSON.stringify(payload),
  })

  return mapItem(item)
}

export async function updateTodoItem(
  todoListId: number,
  id: number,
  payload: SaveTodoItemPayload,
) {
  const item = await request<ApiTodoItem>(`/todolists/${todoListId}/items/${id}`, {
    method: 'PUT',
    body: JSON.stringify(payload),
  })

  return mapItem(item)
}

export async function deleteTodoItem(todoListId: number, id: number) {
  await request<void>(`/todolists/${todoListId}/items/${id}`, { method: 'DELETE' })
}

import { FormEvent, useMemo, useState } from 'react'

type TodoItem = {
  id: string
  title: string
  completed: boolean
}

type TodoList = {
  id: string
  title: string
  description: string
  items: TodoItem[]
}

const initialLists: TodoList[] = [
  {
    id: 'product',
    title: 'Producto',
    description: 'Tareas para ajustar la experiencia inicial.',
    items: [
      { id: 'product-1', title: 'Definir contratos REST', completed: false },
      { id: 'product-2', title: 'Validar estados vacios', completed: true },
      { id: 'product-3', title: 'Revisar copy de acciones', completed: false },
    ],
  },
  {
    id: 'delivery',
    title: 'Delivery',
    description: 'Seguimiento operativo del sprint actual.',
    items: [
      { id: 'delivery-1', title: 'Preparar demo navegable', completed: true },
      { id: 'delivery-2', title: 'Documentar endpoints necesarios', completed: false },
    ],
  },
]

function createId(prefix: string) {
  return `${prefix}-${Date.now().toString(36)}`
}

function App() {
  const [lists, setLists] = useState<TodoList[]>(initialLists)
  const [selectedListId, setSelectedListId] = useState(initialLists[0].id)
  const [newListTitle, setNewListTitle] = useState('')
  const [newItemTitle, setNewItemTitle] = useState('')
  const [editingListId, setEditingListId] = useState<string | null>(null)
  const [editingItemId, setEditingItemId] = useState<string | null>(null)
  const [draftTitle, setDraftTitle] = useState('')

  const selectedList = lists.find((list) => list.id === selectedListId) ?? lists[0]

  const totals = useMemo(() => {
    const itemCount = lists.reduce((count, list) => count + list.items.length, 0)
    const completedCount = lists.reduce(
      (count, list) => count + list.items.filter((item) => item.completed).length,
      0,
    )

    return { itemCount, completedCount, pendingCount: itemCount - completedCount }
  }, [lists])

  function addList(event: FormEvent<HTMLFormElement>) {
    event.preventDefault()

    const title = newListTitle.trim()
    if (!title) {
      return
    }

    const list: TodoList = {
      id: createId('list'),
      title,
      description: 'Nueva lista de trabajo.',
      items: [],
    }

    setLists((currentLists) => [...currentLists, list])
    setSelectedListId(list.id)
    setNewListTitle('')
  }

  function deleteList(listId: string) {
    setLists((currentLists) => {
      const nextLists = currentLists.filter((list) => list.id !== listId)
      if (selectedListId === listId) {
        setSelectedListId(nextLists[0]?.id ?? '')
      }

      return nextLists
    })
  }

  function startListEdit(list: TodoList) {
    setEditingItemId(null)
    setEditingListId(list.id)
    setDraftTitle(list.title)
  }

  function saveListTitle(listId: string) {
    const title = draftTitle.trim()
    if (!title) {
      return
    }

    setLists((currentLists) =>
      currentLists.map((list) => (list.id === listId ? { ...list, title } : list)),
    )
    setEditingListId(null)
    setDraftTitle('')
  }

