      id: createId('item'),
      title,
      completed: false,
    }

    setLists((currentLists) =>
      currentLists.map((list) =>
        list.id === selectedList.id ? { ...list, items: [...list.items, item] } : list,
      ),
    )
    setNewItemTitle('')
  }

  function toggleItem(itemId: string) {
    setLists((currentLists) =>
      currentLists.map((list) =>
        list.id === selectedList.id
          ? {
              ...list,
              items: list.items.map((item) =>
                item.id === itemId ? { ...item, completed: !item.completed } : item,
              ),
            }
          : list,
      ),
    )
  }

  function startItemEdit(item: TodoItem) {
    setEditingListId(null)
    setEditingItemId(item.id)
    setDraftTitle(item.title)
  }

  function saveItemTitle(itemId: string) {
    const title = draftTitle.trim()
    if (!title) {
      return
    }

    setLists((currentLists) =>
      currentLists.map((list) =>
        list.id === selectedList.id
          ? {
              ...list,
              items: list.items.map((item) => (item.id === itemId ? { ...item, title } : item)),
            }
          : list,
      ),
    )
    setEditingItemId(null)
    setDraftTitle('')
  }

  function deleteItem(itemId: string) {
    setLists((currentLists) =>
      currentLists.map((list) =>
        list.id === selectedList.id
          ? { ...list, items: list.items.filter((item) => item.id !== itemId) }
          : list,
      ),
    )
  }

  const selectedCompleted = selectedList.items.filter((item) => item.completed).length
  const selectedPending = selectedList.items.length - selectedCompleted

  return (
    <main className="app-shell">
