import { FormEvent, useCallback, useEffect, useMemo, useState } from 'react'
import {
  ApiError,
  createTodoItem,
  createTodoList,
  deleteTodoItem,
  deleteTodoList,
  getTodoLists,
  updateTodoItem,
  updateTodoList,
} from './api'
import type { TodoItem, TodoList } from './types'

function getErrorMessage(error: unknown) {
  if (error instanceof ApiError) {
    return error.code ? `${error.message} (${error.code})` : error.message
  }

  if (error instanceof Error) {
    return error.message
  }

  return 'No se pudo completar la operacion.'
}

function upsertList(lists: TodoList[], updatedList: TodoList) {
  const exists = lists.some((list) => list.id === updatedList.id)

  if (!exists) {
    return [...lists, updatedList]
  }

  return lists.map((list) => (list.id === updatedList.id ? updatedList : list))
}

function App() {
  const [lists, setLists] = useState<TodoList[]>([])
  const [selectedListId, setSelectedListId] = useState<number | null>(null)
  const [newListTitle, setNewListTitle] = useState('')
  const [newItemTitle, setNewItemTitle] = useState('')
  const [editingListId, setEditingListId] = useState<number | null>(null)
  const [editingItemId, setEditingItemId] = useState<number | null>(null)
  const [draftTitle, setDraftTitle] = useState('')
  const [isLoading, setIsLoading] = useState(true)
  const [isSaving, setIsSaving] = useState(false)
  const [errorMessage, setErrorMessage] = useState<string | null>(null)

  const selectedList = lists.find((list) => list.id === selectedListId) ?? lists[0]

  const loadLists = useCallback(async () => {
    setIsLoading(true)
    setErrorMessage(null)

    try {
      const nextLists = await getTodoLists()
      setLists(nextLists)
      setSelectedListId((currentId) => {
        if (currentId && nextLists.some((list) => list.id === currentId)) {
          return currentId
        }

        return nextLists[0]?.id ?? null
      })
    } catch (error) {
      setErrorMessage(getErrorMessage(error))
    } finally {
      setIsLoading(false)
    }
  }, [])

  useEffect(() => {
    void loadLists()
  }, [loadLists])

  const totals = useMemo(() => {
    const itemCount = lists.reduce((count, list) => count + list.items.length, 0)
    const completedCount = lists.reduce(
      (count, list) => count + list.items.filter((item) => item.completed).length,
      0,
    )

    return { itemCount, completedCount, pendingCount: itemCount - completedCount }
  }, [lists])

  async function addList(event: FormEvent<HTMLFormElement>) {
    event.preventDefault()

    const name = newListTitle.trim()
    if (!name || isSaving) {
      return
    }

    setIsSaving(true)
    setErrorMessage(null)

    try {
      const list = await createTodoList({ name })
      setLists((currentLists) => upsertList(currentLists, list))
      setSelectedListId(list.id)
      setNewListTitle('')
    } catch (error) {
      setErrorMessage(getErrorMessage(error))
    } finally {
      setIsSaving(false)
    }
  }

  async function removeList(listId: number) {
    if (isSaving) {
      return
    }

    setIsSaving(true)
    setErrorMessage(null)

    try {
      await deleteTodoList(listId)
      setLists((currentLists) => {
        const nextLists = currentLists.filter((list) => list.id !== listId)

        if (selectedListId === listId) {
          setSelectedListId(nextLists[0]?.id ?? null)
        }

        return nextLists
      })
    } catch (error) {
      setErrorMessage(getErrorMessage(error))
    } finally {
      setIsSaving(false)
    }
  }

  function startListEdit(list: TodoList) {
    setEditingItemId(null)
    setEditingListId(list.id)
    setDraftTitle(list.title)
  }

  async function saveListTitle(listId: number) {
    const name = draftTitle.trim()
    if (!name || isSaving) {
      return
    }

    setIsSaving(true)
    setErrorMessage(null)

    try {
      const list = await updateTodoList(listId, { name })
      setLists((currentLists) => upsertList(currentLists, list))
      setEditingListId(null)
      setDraftTitle('')
    } catch (error) {
      setErrorMessage(getErrorMessage(error))
    } finally {
      setIsSaving(false)
    }
  }

  async function addItem(event: FormEvent<HTMLFormElement>) {
    event.preventDefault()

    const name = newItemTitle.trim()
    if (!name || !selectedList || isSaving) {
      return
    }

    setIsSaving(true)
    setErrorMessage(null)

    try {
      const item = await createTodoItem(selectedList.id, { name, isCompleted: false })
      setLists((currentLists) =>
        currentLists.map((list) =>
          list.id === selectedList.id ? { ...list, items: [...list.items, item] } : list,
        ),
      )
      setNewItemTitle('')
    } catch (error) {
      setErrorMessage(getErrorMessage(error))
    } finally {
      setIsSaving(false)
    }
  }

  async function toggleItem(item: TodoItem) {
    if (!selectedList || isSaving) {
      return
    }

    setIsSaving(true)
    setErrorMessage(null)

    try {
      const updatedItem = await updateTodoItem(selectedList.id, item.id, {
        name: item.title,
        isCompleted: !item.completed,
      })

      setLists((currentLists) =>
        currentLists.map((list) =>
          list.id === selectedList.id
            ? {
                ...list,
                items: list.items.map((currentItem) =>
                  currentItem.id === item.id ? updatedItem : currentItem,
                ),
              }
            : list,
        ),
      )
    } catch (error) {
      setErrorMessage(getErrorMessage(error))
    } finally {
      setIsSaving(false)
    }
  }

  function startItemEdit(item: TodoItem) {
    setEditingListId(null)
    setEditingItemId(item.id)
    setDraftTitle(item.title)
  }

  async function saveItemTitle(item: TodoItem) {
    const name = draftTitle.trim()
    if (!name || !selectedList || isSaving) {
      return
    }

    setIsSaving(true)
    setErrorMessage(null)

    try {
      const updatedItem = await updateTodoItem(selectedList.id, item.id, {
        name,
        isCompleted: item.completed,
      })

      setLists((currentLists) =>
        currentLists.map((list) =>
          list.id === selectedList.id
            ? {
                ...list,
                items: list.items.map((currentItem) =>
                  currentItem.id === item.id ? updatedItem : currentItem,
                ),
              }
            : list,
        ),
      )
      setEditingItemId(null)
      setDraftTitle('')
    } catch (error) {
      setErrorMessage(getErrorMessage(error))
    } finally {
      setIsSaving(false)
    }
  }

  async function removeItem(itemId: number) {
    if (!selectedList || isSaving) {
      return
    }

    setIsSaving(true)
    setErrorMessage(null)

    try {
      await deleteTodoItem(selectedList.id, itemId)
      setLists((currentLists) =>
        currentLists.map((list) =>
          list.id === selectedList.id
            ? { ...list, items: list.items.filter((item) => item.id !== itemId) }
            : list,
        ),
      )
    } catch (error) {
      setErrorMessage(getErrorMessage(error))
    } finally {
      setIsSaving(false)
    }
  }

  const selectedCompleted = selectedList?.items.filter((item) => item.completed).length ?? 0
  const selectedPending = selectedList ? selectedList.items.length - selectedCompleted : 0

  return (
    <main className="app-shell">
      <aside className="sidebar" aria-label="Todo lists">
        <div className="brand">
          <span className="brand-mark" aria-hidden="true">
            TD
          </span>
          <div>
            <h1>TodoList</h1>
            <p>API REST local</p>
          </div>
        </div>

        <form className="compact-form" onSubmit={addList}>
          <input
            aria-label="Nombre de nueva lista"
            disabled={isSaving}
            onChange={(event) => setNewListTitle(event.target.value)}
            placeholder="Nueva lista"
            value={newListTitle}
          />
          <button disabled={isSaving} type="submit">
            Add
          </button>
        </form>

        <nav className="list-nav">
          {lists.map((list) => (
            <button
              className={list.id === selectedList?.id ? 'list-link active' : 'list-link'}
              key={list.id}
              onClick={() => setSelectedListId(list.id)}
              type="button"
            >
              <span>{list.title}</span>
              <small>{list.items.length}</small>
            </button>
          ))}
        </nav>
      </aside>

      <section className="workspace" aria-label="Selected todo list">
        <div className="status-row">
          <span>{isLoading ? 'Cargando datos...' : 'Conectado a TodoApi'}</span>
          <button disabled={isLoading || isSaving} onClick={loadLists} type="button">
            Refresh
          </button>
        </div>

        {errorMessage ? <div className="error-banner">{errorMessage}</div> : null}

        {!selectedList && !isLoading ? (
          <div className="empty-state">
            <strong>No hay listas</strong>
            <span>Crea una lista para empezar a gestionar items.</span>
          </div>
        ) : null}

        {selectedList ? (
          <>
            <header className="workspace-header">
              <div>
                {editingListId === selectedList.id ? (
                  <div className="edit-row">
                    <input
                      aria-label="Editar nombre de lista"
                      autoFocus
                      disabled={isSaving}
                      onChange={(event) => setDraftTitle(event.target.value)}
                      value={draftTitle}
                    />
                    <button
                      disabled={isSaving}
                      onClick={() => saveListTitle(selectedList.id)}
                      type="button"
                    >
                      Save
                    </button>
                  </div>
                ) : (
                  <h2>{selectedList.title}</h2>
                )}
                <p>{selectedList.description}</p>
              </div>

              <div className="header-actions">
                <button disabled={isSaving} onClick={() => startListEdit(selectedList)} type="button">
                  Edit
                </button>
                <button
                  className="danger"
                  disabled={isSaving}
                  onClick={() => removeList(selectedList.id)}
                  type="button"
                >
                  Delete
                </button>
              </div>
            </header>

            <form className="item-form" onSubmit={addItem}>
              <input
                aria-label="Nuevo item"
                disabled={isSaving}
                onChange={(event) => setNewItemTitle(event.target.value)}
                placeholder="Agregar item a esta lista"
                value={newItemTitle}
              />
              <button disabled={isSaving} type="submit">
                Add item
              </button>
            </form>

            <div className="item-list">
              {selectedList.items.length === 0 ? (
                <div className="empty-state">
                  <strong>No hay items</strong>
                  <span>Agrega el primer item para empezar a trabajar esta lista.</span>
                </div>
              ) : (
                selectedList.items.map((item) => (
                  <article
                    className={item.completed ? 'todo-item completed' : 'todo-item'}
                    key={item.id}
                  >
                    <label>
                      <input
                        checked={item.completed}
                        disabled={isSaving}
                        onChange={() => toggleItem(item)}
                        type="checkbox"
                      />
                      {editingItemId === item.id ? (
                        <input
                          aria-label="Editar item"
                          autoFocus
                          className="inline-input"
                          disabled={isSaving}
                          onChange={(event) => setDraftTitle(event.target.value)}
                          value={draftTitle}
                        />
                      ) : (
                        <span>{item.title}</span>
                      )}
                    </label>

                    <div className="row-actions">
                      {editingItemId === item.id ? (
                        <button disabled={isSaving} onClick={() => saveItemTitle(item)} type="button">
                          Save
                        </button>
                      ) : (
                        <button disabled={isSaving} onClick={() => startItemEdit(item)} type="button">
                          Edit
                        </button>
                      )}
                      <button
                        className="danger"
                        disabled={isSaving}
                        onClick={() => removeItem(item.id)}
                        type="button"
                      >
                        Delete
                      </button>
                    </div>
                  </article>
                ))
              )}
            </div>
          </>
        ) : null}
      </section>

      <aside className="inspector" aria-label="Summary">
        <h2>Resumen</h2>
        <dl>
          <div>
            <dt>Listas</dt>
            <dd>{lists.length}</dd>
          </div>
          <div>
            <dt>Items</dt>
            <dd>{totals.itemCount}</dd>
          </div>
          <div>
            <dt>Pendientes</dt>
            <dd>{totals.pendingCount}</dd>
          </div>
          <div>
            <dt>Completados</dt>
            <dd>{totals.completedCount}</dd>
          </div>
        </dl>

        <div className="selected-summary">
          <span>Lista actual</span>
          <strong>{selectedList?.title ?? 'Sin seleccion'}</strong>
          <p>
            {selectedPending} pendientes, {selectedCompleted} completados.
          </p>
        </div>
      </aside>
    </main>
  )
}

export default App

