  const selectedList = lists.find((list) => list.id === selectedListId) ?? lists[0]

  const loadLists = useCallback(async () => {
    setIsLoading(true)
    setErrorMessage(null)

    try {
      const nextLists = await getTodoLists()
      setLists(nextLists)
      setSelectedListId((currentId) => {
        if (currentId && nextLists.some((list) => list.id === currentId)) {
          return currentId
        }

        return nextLists[0]?.id ?? null
      })
    } catch (error) {
      setErrorMessage(getErrorMessage(error))
    } finally {
      setIsLoading(false)
    }
  }, [])

  useEffect(() => {
    void loadLists()
  }, [loadLists])

  const totals = useMemo(() => {
    const itemCount = lists.reduce((count, list) => count + list.items.length, 0)
    const completedCount = lists.reduce(
      (count, list) => count + list.items.filter((item) => item.completed).length,
      0,
