  editingListId: number | null
  editingItemId: number | null
  draftTitle: string
  errorMessage: string | null
  isLoading: boolean
  isSaving: boolean
  newItemTitle: string
  onAddItem: (event: FormEvent<HTMLFormElement>) => void
  onDeleteItem: (id: number) => void
  onDeleteList: (id: number) => void
  onDraftTitleChange: (value: string) => void
  onEditItem: (item: TodoItem) => void
  onEditList: (list: TodoList) => void
  onNewItemTitleChange: (value: string) => void
  onRefresh: () => void
  onSaveItemTitle: (item: TodoItem) => void
  onSaveListTitle: (id: number) => void
  onToggleItem: (item: TodoItem) => void
}

export function Workspace({
  selectedList,
  editingListId,
  editingItemId,
  draftTitle,
  errorMessage,
  isLoading,
  isSaving,
  newItemTitle,
  onAddItem,
  onDeleteItem,
  onDeleteList,
  onDraftTitleChange,
  onEditItem,
  onEditList,
  onNewItemTitleChange,
  onRefresh,
  onSaveItemTitle,
  onSaveListTitle,
  onToggleItem,
