                    onChange={(event) => onDraftTitleChange(event.target.value)}
                    value={draftTitle}
                  />
                  <button
                    disabled={isSaving || !draftTitle.trim()}
                    onClick={() => onSaveListTitle(selectedList.id)}
                    type="button"
                  >
                    Save
                  </button>
                </div>
              ) : (
                <h2>{selectedList.title}</h2>
              )}
