        onNewItemTitleChange={setNewItemTitle}
        onRefresh={loadLists}
        onSaveItemTitle={saveItemTitle}
        onSaveListTitle={saveListTitle}
        onToggleItem={toggleItem}
        selectedList={selectedList}
      />

      <Inspector
        lists={lists}
        selectedCompleted={selectedCompleted}
