}

function replaceItem(lists: TodoList[], listId: number, updatedItem: TodoItem) {
  return lists.map((list) =>
    list.id === listId
      ? {
          ...list,
          items: list.items.map((item) => (item.id === updatedItem.id ? updatedItem : item)),
        }
      : list,
  )
}

